// Daily (evening) and weekly (Sunday) recaps, generated by the model from the user's logs
// and posted into their chat. Optional per deployment (RECAPS_ENABLED) and per user.
import { config } from "../config";
import { prisma } from "../db";
import { sendEmail } from "../email";
import { createProvider, modelFor } from "../llm";
import { log } from "../log";
import { addDays, localDay, localHour, localWeekday } from "../time";
import { loadPrompt } from "./context";
import { todaySnapshot } from "./logs";
import { getProfile } from "./profile";
import { dayLines, exerciseLine, mealLine } from "./totals";
import { checkSpend, recordUsage } from "./spend";

export type RecapKind = "daily" | "weekly";

/** Which recap (if any) is due for this user right now. */
export function recapDue(
  u: { timezone: string; recapDaily: boolean; recapWeekly: boolean; lastDailyRecap: string | null; lastWeeklyRecap: string | null },
  now: Date,
  hour: number,
): RecapKind | null {
  if (localHour(now, u.timezone) < hour) return null;
  const today = localDay(now, u.timezone);
  const sunday = localWeekday(now, u.timezone) === "Sun";
  if (sunday && u.recapWeekly && u.lastWeeklyRecap !== today) return "weekly";
  if (u.recapDaily && u.lastDailyRecap !== today && !(sunday && u.recapWeekly)) return "daily";
  return null;
}

export async function generateRecap(userId: string, kind: RecapKind, now = new Date()) {
  const c = config();
  const user = await prisma.user.findUniqueOrThrow({ where: { id: userId } });
  const tz = user.timezone;
  const today = localDay(now, tz);
  const blocked = await checkSpend(user.id, user.plan, now);
  if (blocked) return null;

  const profile = await getProfile(user.id);
  let data: string;
  if (kind === "daily") {
    const snap = await todaySnapshot(user.id, tz, now);
    data = [
      `Targets: ${JSON.stringify(profile.data.targets ?? {})}`,
      `Today ${today} totals: ${JSON.stringify(snap.totals)}`,
      "Meals:\n" + (snap.meals.map((m) => mealLine(m, tz)).join("\n") || "none"),
      "Exercise:\n" + (snap.exercises.map((x) => exerciseLine(x, tz)).join("\n") || "none"),
      snap.lastWeight ? `Last weigh-in: ${snap.lastWeight.day} ${snap.lastWeight.weight} ${snap.lastWeight.unit}` : "",
    ].join("\n");
  } else {
    const from = addDays(today, -13);
    const where = { userId: user.id, day: { gte: from, lte: today } };
    const [meals, exercises, weights] = await Promise.all([
      prisma.mealLog.findMany({ where }),
      prisma.exerciseLog.findMany({ where }),
      prisma.weightLog.findMany({ where }),
    ]);
    data = [
      `Targets: ${JSON.stringify(profile.data.targets ?? {})}`,
      `Goal: ${String(profile.data.goal ?? "not set")}`,
      "Previous week:\n" + dayLines(addDays(today, -6), 7, meals, exercises, weights).join("\n"),
      "This week:\n" + dayLines(addDays(today, 1), 7, meals, exercises, weights).join("\n"),
    ].join("\n");
  }

  const prompt = loadPrompt("recap")
    .replaceAll("{{period}}", kind === "daily" ? "end-of-day" : "weekly")
    .replaceAll("{{next}}", kind === "daily" ? "tomorrow" : "next week")
    .replaceAll("{{length}}", kind === "daily" ? "2-4 sentences" : "5-8 short lines");

  const choice = modelFor("recap")!;
  const provider = createProvider(choice.provider);
  const res = await provider.chat({
    model: choice.model,
    system: [{ text: prompt }, { text: `Profile: ${JSON.stringify(profile.data)}` }],
    messages: [{ role: "user", content: [{ type: "text", text: data }] }],
    maxTokens: Math.min(c.limits.maxOutputTokens, 500),
  });
  await recordUsage({ userId: user.id, kind: "recap", provider: provider.name, model: choice.model, usage: res.usage });
  const text = res.text.trim();
  if (!text) return null;

  await prisma.message.create({ data: { userId: user.id, role: "assistant", content: text, kind: "recap" } });
  await prisma.user.update({
    where: { id: user.id },
    data: kind === "daily" ? { lastDailyRecap: today } : { lastWeeklyRecap: today, lastDailyRecap: today },
  });
  if (c.recaps.email) {
    await sendEmail({
      to: user.email,
      subject: kind === "daily" ? "Your Vortra daily recap" : "Your Vortra weekly recap",
      text: `${text}\n\nOpen Vortra: ${c.appUrl}`,
    }).catch(() => log.warn("recap_email_failed", { userId: user.id }));
  }
  return text;
}

/** Run once (hourly or more often). Sends due recaps to active users, one at a time. */
export async function runRecaps(now = new Date()) {
  const c = config();
  if (!c.recaps.enabled) return { sent: 0, skipped: "disabled" };
  const activeSince = new Date(now.getTime() - 7 * 24 * 3600 * 1000);
  const users = await prisma.user.findMany({
    where: {
      OR: [{ recapDaily: true }, { recapWeekly: true }],
      messages: { some: { role: "user", createdAt: { gte: activeSince } } },
    },
    select: { id: true, timezone: true, recapDaily: true, recapWeekly: true, lastDailyRecap: true, lastWeeklyRecap: true },
  });
  let sent = 0;
  for (const u of users) {
    const kind = recapDue(u, now, c.recaps.hour);
    if (!kind) continue;
    try {
      if (await generateRecap(u.id, kind, now)) sent++;
    } catch {
      log.error("recap_failed", { userId: u.id, kind });
    }
  }
  log.info("recaps_run", { candidates: users.length, sent });
  return { sent };
}
